/bin/bash -lc "cat > /workspace/openai_client.py << 'PYEOF'
\"\"\"Private text-prompt client for OpenAI's Responses API.

Uses only the Python standard library so there are no third-party
dependencies to install. The API key and any prompt text are kept
private: nothing is printed to stdout/stderr, and the key is never
exposed in error messages or tracebacks.
\"\"\"

import json
import os
import urllib.error
import urllib.request

API_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4o\"


class OpenAIClientError(RuntimeError):
    \"\"\"Raised when a request to the Responses API fails.\"\"\"


class OpenAIClient:
    \"\"\"Minimal client for sending text prompts to the Responses API.\"\"\"

    def __init__(self, api_key=None, model=DEFAULT_MODEL, timeout=60):
        # Resolve the key from the argument or the environment, but never
        # store or surface it in logs.
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise OpenAIClientError(
                \"No API key found. Pass api_key=... or set OPENAI_API_KEY.\"
            )
        self.model = model
        self.timeout = timeout

    def create(self, prompt, model=None, temperature=None, **extra):
        \"\"\"Send a single text prompt and return the model's text reply.

        Args:
            prompt: The private text prompt (str).
            model: Optional model override for this call.
            temperature: Optional sampling temperature.
            **extra: Any additional fields merged into the request body.

        Returns:
            The assistant's text response as a string.
        \"\"\"
        body = {
            \"model\": model or self.model,
            \"input\": prompt,
        }
        if temperature is not None:
            body[\"temperature\"] = temperature
        body.update(extra)

        data = json.dumps(body).encode(\"utf-8\")
        request = urllib.request.Request(
            API_URL,
            data=data,
            method=\"POST\",
            headers={
                \"Content-Type\": \"application/json\",
                \"Authorization\": \"Bearer \" + self.api_key,
            },
        )

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as resp:
                payload = json.loads(resp.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode(\"utf-8\", \"replace\")
            raise OpenAIClientError(
                \"Responses API request failed (status %s).\" % exc.code
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIClientError(
                \"Could not reach the Responses API.\"
            ) from exc

        return self._extract_text(payload)

    @staticmethod
    def _extract_text(payload):
        \"\"\"Pull the assistant text out of a Responses API payload.\"\"\"
        # Newer responses include a convenience field.
        if \"output_text\" in payload and payload[\"output_text\"]:
            return payload[\"output_text\"]

        parts = []
        for item in payload.get(\"output\", []):
            for content in item.get(\"content\", []):
                if content.get(\"type\") == \"output_text\":
                    parts.append(content.get(\"text\", \"\"))
        return \"\".join(parts)


def main():
    \"\"\"Tiny CLI so the module is runnable: "'`python openai_client.py`."""
    import sys

    prompt = " ".join(sys.argv[1:]) or "Say hello in one short sentence."
    client = OpenAIClient()
    try:
        print(client.create(prompt))
    except OpenAIClientError as exc:
        print("Error: " + str(exc), file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
PYEOF
